svg.script:
(() => {
  const svg=document.documentElement, W=svg.viewBox.baseVal.width, H=svg.viewBox.baseVal.height;
  const CX=W/2, CY=H/2, rand=(a,b)=>a+Math.random()*(b-a);
  const els=[...svg.querySelectorAll('.node')], byId=new Map();
  const nodes=els.map(el=>{
    const ports=el.dataset.ports.split(';').map(p=>p.split(',').map(Number));
    const n={id:el.dataset.id,el,body:el.querySelector('.body'),icon:el.querySelector('.icon'),
      x:+el.dataset.x,y:+el.dataset.y,ox:+el.dataset.oldX,oy:+el.dataset.oldY,r:+el.dataset.radius,
      ports,a:rand(0,360),ia:rand(0,360),av:rand(2,6)*(Math.random()<.5?-1:1),
      iav:rand(8,18)*(Math.random()<.5?-1:1),vx:0,vy:0,fixed:el.dataset.id==='root'};
    byId.set(n.id,n); return n;
  });
  const edges=[...svg.querySelectorAll('#connectors line')].map(el=>({el,a:byId.get(el.dataset.a),b:byId.get(el.dataset.b)}));
  const root=byId.get('root');

  function matrix(n,deg,tx=n.x,ty=n.y){
    const q=deg*Math.PI/180,c=Math.cos(q),s=Math.sin(q);
    const e=tx-c*n.ox+s*n.oy, f=ty-s*n.ox-c*n.oy;
    return `matrix(${c} ${s} ${-s} ${c} ${e} ${f})`;
  }
  function rotate(v,deg){const q=deg*Math.PI/180,c=Math.cos(q),s=Math.sin(q);return [v[0]*c-v[1]*s,v[0]*s+v[1]*c];}
  function portFor(n,o){
    const dx=o.x-n.x,dy=o.y-n.y,d=Math.hypot(dx,dy)||1,ux=dx/d,uy=dy/d; let best=null,bs=-Infinity;
    for(const v of n.ports){const p=rotate(v,n.a),s=p[0]*ux+p[1]*uy;if(s>bs){bs=s;best=[n.x+p[0],n.y+p[1]];}}
    return best;
  }
  function update(){
    for(const n of nodes){
      n.body.setAttribute('transform',matrix(n,n.a));
      // The root icon is tied to the exact image center, not to the root node transform.
      n.icon.setAttribute('transform', n.id==='root' ? matrix(n,n.ia,CX,CY) : matrix(n,n.ia));
    }
    for(const e of edges){const p=portFor(e.a,e.b),q=portFor(e.b,e.a);e.el.setAttribute('x1',p[0]);e.el.setAttribute('y1',p[1]);e.el.setAttribute('x2',q[0]);e.el.setAttribute('y2',q[1]);}
  }

  // Repulsion tries to maximize separation; long weak springs preserve the original tree topology.
  function atomize(dt){
    const fx=new Map(nodes.map(n=>[n,0])),fy=new Map(nodes.map(n=>[n,0]));
    for(let i=0;i<nodes.length;i++)for(let j=i+1;j<nodes.length;j++){
      const a=nodes[i],b=nodes[j]; let dx=a.x-b.x,dy=a.y-b.y,d2=dx*dx+dy*dy;
      if(d2<1){dx=rand(-1,1);dy=rand(-1,1);d2=dx*dx+dy*dy;}
      const d=Math.sqrt(d2),ux=dx/d,uy=dy/d,gap=Math.max(1,d-a.r-b.r),mag=Math.min(90,145000/(gap+70));
      fx.set(a,fx.get(a)+ux*mag);fy.set(a,fy.get(a)+uy*mag);fx.set(b,fx.get(b)-ux*mag);fy.set(b,fy.get(b)-uy*mag);
    }
    for(const e of edges){
      const a=e.a,b=e.b,dx=b.x-a.x,dy=b.y-a.y,d=Math.hypot(dx,dy)||1,ux=dx/d,uy=dy/d;
      const target=(a.id==='root'||b.id==='root')?525:405,mag=(d-target)*.20;
      fx.set(a,fx.get(a)+ux*mag);fy.set(a,fy.get(a)+uy*mag);fx.set(b,fx.get(b)-ux*mag);fy.set(b,fy.get(b)-uy*mag);
    }
    for(const n of nodes){
      if(n.fixed){n.x=CX;n.y=CY;n.vx=n.vy=0;continue;}
      n.vx=(n.vx+fx.get(n)*dt)*.90;n.vy=(n.vy+fy.get(n)*dt)*.90;
      const vmax=62,v=Math.hypot(n.vx,n.vy);if(v>vmax){n.vx*=vmax/v;n.vy*=vmax/v;}
      n.x+=n.vx*dt;n.y+=n.vy*dt;
      const m=n.r+19;
      if(n.x<m){n.x=m;n.vx=Math.abs(n.vx)*.2;}if(n.x>W-m){n.x=W-m;n.vx=-Math.abs(n.vx)*.2;}
      if(n.y<m){n.y=m;n.vy=Math.abs(n.vy)*.2;}if(n.y>H-m){n.y=H-m;n.vy=-Math.abs(n.vy)*.2;}
    }
  }
  let last=performance.now(),settle=0;
  function frame(now){
    const dt=Math.min(.033,(now-last)/1000||.016);last=now;
    if(settle<10){atomize(dt);settle+=dt;}
    for(const n of nodes){n.a=(n.a+n.av*dt)%360;n.ia=(n.ia+n.iav*dt)%360;}
    update();requestAnimationFrame(frame);
  }
  update();requestAnimationFrame(frame);
})();
